    private static let ring = IconShape(d: "M7.06833 1.43945C7.81912 1.43945 8.54825 1.58383 9.25572 1.8726C9.96319 2.14692 10.584 2.53675 11.1182 3.04209C11.6525 3.54743 12.0784 4.15383 12.396 4.8613C12.7281 5.55433 12.8941 6.31233 12.8941 7.13531C12.8941 7.97272 12.7353 8.74517 12.4177 9.45264C12.1 10.1601 11.6741 10.7737 11.1399 11.2935C10.6201 11.8133 10.0065 12.2175 9.29903 12.5063C8.606 12.7951 7.86965 12.9395 7.08999 12.9395C6.31033 12.9395 5.56676 12.8023 4.85929 12.528C4.15182 12.2536 3.52376 11.8638 2.97511 11.3585C2.4409 10.8531 2.00776 10.2467 1.67568 9.53926C1.35804 8.83179 1.19922 8.05213 1.19922 7.20028C1.19922 6.23292 1.3797 5.38829 1.74065 4.66638C2.11604 3.94447 2.58528 3.34529 3.14837 2.86883C3.7259 2.39237 4.36118 2.03864 5.05421 1.80763C5.74724 1.56218 6.41862 1.43945 7.06833 1.43945Z")
    private static let check = IconShape(d: "M5 6.4L7.09922 8L10.4992 3.5")

    var body: some View {
        GeometryReader { g in
            let scale = min(g.size.width, g.size.height) / 14
            ZStack {
                Self.ring.stroke(lineWidth: 2.8 * scale).clipShape(Self.ring)
                Self.check.stroke(lineWidth: 1.4 * scale)
            }
        }
    }
}
